sp_widget.client_script:
function($scope, spModal) {
    var c = this;

    // 打开UI Page模态框
    c.openUIPage = function() {
        // 获取UI Page的sys_id（从系统中查询或由管理员提供）
        var uiPageSysId = 'e72e86c197b9a210d078f62de053af25';

        // 使用spModal打开UI Page
        spModal.open({
            title: 'UI Page内容',
            size: 'lg', // 模态框大小：sm/md/lg
            templateUrl: '/$sp.ui.page.render.do?sys_id=' + uiPageSysId,

            // 传递参数到UI Page（可选）
            resolve: {
                record: $scope.options.record, // 当前记录
                customParam: '自定义参数值'
            }
        }).then(
            function(response) {
                // 点击"确定"后的回调
                console.log('用户点击了确定，返回数据:', response);
                $scope.$emit('sp.show.message', {
                    message: '操作成功!',
                    type: 'success'
                });
            },
            function(error) {
                // 点击"取消"或错误处理
                console.log('用户取消或发生错误:', error);
            }
        );
    };
}
